requested=next(p for p in Path('/sys/class/remoteproc').glob('*') if (p/'name').read_text().strip()=='modem');param=Path('/sys/module/firmware_class/parameters/path').read_text().strip();base=(Path(param)/(requested/'firmware').read_text().strip()).parent;expected={line.split()[1]:line.split()[0] for line in Path('/etc/samurai-wifi/modem-sha256.txt').read_text().splitlines()};checks={name:hashlib.sha256((base/name).read_bytes()).hexdigest()==digest for name,digest in expected.items()};assert len(checks)==34 and all(checks.values())
for name,expected in [('rmtfs','d1ca1fc4087e47f1618e09f568605f2f253eac8721598fc930d1eb8c604fe251'),('tftp','b3bb82b9d090a5d06e9ba2ca24e3373ab1c1e7cc2a5c6b603e2acb02715487a1')]:
 pid=int(Path('/run/samurai-wifi',name+'.pid').read_text());assert hashlib.sha256(Path('/proc',str(pid),'exe').read_bytes()).hexdigest()==expected
