bus=dbus.SystemBus(private=True);objects=dbus.Interface(bus.get_object('org.freedesktop.ModemManager1','/org/freedesktop/ModemManager1'),'org.freedesktop.DBus.ObjectManager').GetManagedObjects();v=next(x for x in objects.values() if 'org.freedesktop.ModemManager1.Modem' in x);loc=v['org.freedesktop.ModemManager1.Modem.Location'];watch=json.loads((r/'gnss-assist/watch-state.json').read_text());assert int(loc['Enabled'])==0 and not loc['SignalsLocation'] and not watch['active'];bus.close();dm=subprocess.check_output(['dmesg']).decode();faults={k:dm.count(v) for k,v in dict(warning='WARNING:',oops='Oops:',gpu='gpu fault:',dsp_fatal='fatal error received').items()};qrtr=subprocess.check_output(['qrtr-lookup']).decode();owned=[line for line in qrtr.splitlines() if len(line.split())>=5 and line.split()[0] in ['52','4097'] and line.split()[3]=='1'];assert not owned
mount=next(x.split() for x in Path('/proc/mounts').read_text().splitlines() if x.split()[1]=='/');assert mount[0]=='/dev/sda16' and mount[2]=='f2fs';assert os.uname().version.startswith('#183 ') and Path('/proc/sys/kernel/tainted').read_text().strip()=='0' and not any(faults.values())
